const toast = ref({ visible: false, type: 'info', message: '', retry: null });
let toastTimer = null;
function showToast(message, { type = 'info', duration = 2000, retry = null } = {}) {
  if (toastTimer) { clearTimeout(toastTimer); toastTimer = null; }
  toast.value = { visible: true, type, message, retry };
  if (duration > 0) {
    toastTimer = setTimeout(() => {
      toast.value = { visible: false, type: 'info', message: '', retry: null };
      toastTimer = null;
    }, duration);
  }
}
function dismissToast() {
  if (toastTimer) { clearTimeout(toastTimer); toastTimer = null; }
  toast.value = { visible: false, type: 'info', message: '', retry: null };
}
function handleToastRetry() {
  const fn = toast.value.retry;
  dismissToast();
  if (typeof fn === 'function') fn();
}

