/**
 * Guard: clearing Paid while an invoice has recorded payments must return 409
 * with detailed warnings so the UI can surface the conflict before proceeding.
 */
public function test_clear_paid_with_linked_invoice_payment_returns_409_without_force(): void
{
    $token = $this->createDirectorToken([1]);
    $student = $this->createStudent();
    $sc = $this->createStudentClass($student->id, [
        'Paid' => 1,
        'PayDate' => '2026-04-10',
    ]);

    $invoice = \App\Models\Invoice::create([
        'StudentID' => $student->id,
        'StudentClassID' => $sc->ID,
        'IssueDate' => now()->toDateString(),
        'TotalAmount' => 16500,
        'PaidAmount' => 16500,
        'Status' => 'paid',
    ]);
    \App\Models\Payment::create([
        'InvoiceID' => $invoice->id,
        'Amount' => 16500,
        'PaidAt' => '2026-04-10',
        'Method' => 'cash',
    ]);

    $res = $this->putJson(
        "/api/v1/student-classes/{$sc->ID}",
        ['payment_status' => 'unpaid', 'paid_at' => null],
        ['Authorization' => "Bearer {$token}"]
    );

    $res->assertStatus(409);
    $res->assertJsonPath('error', 'payment_linked');
    $res->assertJsonPath('warnings.payment_count', 1);
    $res->assertJsonPath('warnings.total_paid_amount', 16500);
    $res->assertJsonPath('warnings.force_field', 'force_clear_paid');

    $sc->refresh();
    $this->assertSame(1, (int) $sc->Paid, 'Paid must remain 1 when guard blocks the clear');
    $this->assertNotNull($sc->PayDate, 'PayDate must be preserved when guard blocks');
}

/**
 * With force_clear_paid=true the guard lets the clear through. Invoice and
 * Payment rows are intentionally left untouched so accounting can reconcile
 * via the void flow; StudentClass Paid/PayDate are cleared and logged.
 */
public function test_clear_paid_with_force_flag_succeeds(): void
{
    $token = $this->createDirectorToken([1]);
    $student = $this->createStudent();
    $sc = $this->createStudentClass($student->id, [
        'Paid' => 1,
        'PayDate' => '2026-04-10',
    ]);

    $invoice = \App\Models\Invoice::create([
        'StudentID' => $student->id,
        'StudentClassID' => $sc->ID,
        'IssueDate' => now()->toDateString(),
        'TotalAmount' => 16500,
        'PaidAmount' => 16500,
        'Status' => 'paid',
    ]);
    \App\Models\Payment::create([
        'InvoiceID' => $invoice->id,
        'Amount' => 16500,
        'PaidAt' => '2026-04-10',
        'Method' => 'cash',
    ]);

    $res = $this->putJson(
        "/api/v1/student-classes/{$sc->ID}",
        [
            'payment_status' => 'unpaid',
            'paid_at' => null,
            'force_clear_paid' => true,
        ],
        ['Authorization' => "Bearer {$token}"]
    );

    $res->assertOk();
    $sc->refresh();
    $this->assertSame(0, (int) $sc->Paid);
    $this->assertNull($sc->PayDate);
    // Invoice/Payment rows are NOT silently deleted — accounting must go through void flow.
    $this->assertDatabaseHas('Payment', ['InvoiceID' => $invoice->id, 'Amount' => 16500]);
    $this->assertDatabaseHas('Invoice', ['id' => $invoice->id, 'Status' => 'paid']);
}

